  def lucide_icon(name, **options)
    geometry = ICONS.fetch(name.to_s)
    classes = ['cb-icon', "cb-icon--#{name}", options.delete(:class)].compact.join(' ')
    attributes = { xmlns: 'http://www.w3.org/2000/svg', viewBox: '0 0 24 24',
                   width: '1em', height: '1em', fill: 'none', stroke: 'currentColor',
                   'stroke-width' => 2, 'stroke-linecap' => 'round', 'stroke-linejoin' => 'round',
                   'aria-hidden' => 'true', focusable: 'false' }.merge(options).merge(class: classes)
    content_tag(:svg, geometry.html_safe, attributes)
  end
